"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["52632"],{24314(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_fada.sem_municipios","status":422,"titulo":"A base legal do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA) deve abranger pelo menos um munic\xedpio"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_fada.sem_municipios","requisitos":[],"oQueAconteceu":["A configura\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso chegou \xe0 confer\xeancia com a\\nbase legal sem nenhum munic\xedpio abrangido. O fator s\xf3 vale para os munic\xedpios que a base\\nlegal cita, e uma base legal sem munic\xedpio n\xe3o alcan\xe7a ningu\xe9m.","O cadastro de bases legais do fator, em Configura\xe7\xe3o, n\xe3o aceita base legal sem pelo menos um\\nmunic\xedpio, e a declara\xe7\xe3o copia os munic\xedpios desse cadastro. Por isso, na declara\xe7\xe3o, esta\\nrecusa n\xe3o \xe9 esperada: a confer\xeancia existe para que a mesma regra valha tamb\xe9m quando o\\nsistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o publicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como\\numa viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se refere \xe0 vers\xe3o congelada."],"comoResolver":["Se o erro apareceu na declara\xe7\xe3o, confira no cadastro de bases legais do Fator de Atenua\xe7\xe3o\\n(Configura\xe7\xe3o) se a base legal informada tem munic\xedpios e acione a equipe t\xe9cnica do Uni+,\\nporque o cadastro n\xe3o deveria permitir essa situa\xe7\xe3o.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do fada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);